"""
    Finds the kth largest element in the given array arr of integers,
    :param: arr unsorted array of integers
    :param: k, the order of value to return
    :return: kth largest element in array
    :rtype: int
    """
def find_kth(arr: Any, k: Any) -> object {
    if (not isinstance(k, (int, float)) or (k < 0)) {
        raise ValueError("Expected k to be a valid number");
    }
    if (((k == 1) or (k == 0)) or (k > len(arr))) {
        return max(arr);
    }
    kth = int(k);
    current_max = max(arr);
    new_array = `list(filter(lambda (x: Any) { (x != current_max); }, arr));
    return find_kth(new_array, (kth - 1));
}

"""! @brief Create 16-digit hexadecimal string from 64-bit register value"""
def u64_to_hex16le(val: Any) -> object {
    return ''.join(
        ("%02x" % (x & 255))
        for x in (
            val,
            (val >> 8),
            (val >> 16),
            (val >> 24),
            (val >> 32),
            (val >> 40),
            (val >> 48),
            (val >> 56)
        )
    );
}

